SELECT COUNT(*) FROM users as u, postHistory as ph WHERE u.Id = ph.UserId AND u.Views>=0 AND u.DownVotes>=0 AND u.UpVotes>=0 AND u.UpVotes<=62 AND u.CreationDate>='2010-07-27 17:10:30'::timestamp AND u.CreationDate<='2014-07-31 18:48:36'::timestamp AND ph.PostHistoryTypeId=2 AND ph.CreationDate<='2014-08-01 13:56:22'::timestamp;